css:
.aha-social-proofs{
  container:aha-social-proofs / inline-size;
  background:var(--aha-white);
  font-family:var(--aha-font-product);
}
.aha-social-proofs *{box-sizing:border-box}
.aha-social-proofs__badges{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);padding:var(--aha-space-32) var(--aha-space-16)}
.aha-social-proofs__badge{display:block;width:100%;max-width:80px;border-radius:var(--aha-radius-xs)}
.aha-social-proofs__badge img{display:block;width:100%;height:auto}
.aha-social-proofs__badge--wide img{width:110%;max-width:none}
.aha-social-proofs__badge:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
@container aha-social-proofs (max-width:767px){
  .aha-social-proofs__badge{aspect-ratio:80 / 81}
  .aha-social-proofs__badge img{height:100%;object-fit:contain}
  .aha-social-proofs__badge--wide img{width:110%;height:100%}
}
